    files++;
    bytes += size;
    perRoot.set(root, (perRoot.get(root) ?? 0) + 1);
    if (files > limits.maxFiles) throw new WorktreeError(`refusing to copy: more than ${limits.maxFiles} files match (file limit); narrow ${INCLUDE_FILE}`);
    if (bytes > limits.maxBytes) throw new WorktreeError(`refusing to copy: the files exceed the ${limits.maxBytes} byte limit; narrow ${INCLUDE_FILE}`);
  };

