  const safeDirs = new Map<string, boolean>();
  const destOk = (rel: string): boolean => {
    const dir = path.dirname(rel);
    if (!safeDirs.has(dir)) safeDirs.set(dir, ancestryProblem(destRoot, path.join(destRoot, dir === "." ? "" : dir, ".")) === undefined);
